 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* mergeKLists(vector<ListNode*>& lists) {
        map<int,int> mp;
        for(int i=0;i<lists.size();i++)
        {
            auto it=lists[i];
            while(it)
            {
                mp[it->val]++;
                it=it->next;
            }
        }
        ListNode newhead(0);
        ListNode *temp=&newhead;
        for(auto it:mp)
        {
            while(it.second)
            {
                temp->next=new ListNode(it.first);
                it.second--;
                temp=temp->next;
            }
        }
        return newhead.next;
    }
};

